SELECT s.login_session_id::TEXT AS row_id, s.member_id,
COALESCE(m.nickname, CONVERT_FROM(DECRYPT(DECODE(m.name,'HEX'),#{cryptoKey}::BYTEA,'AES'),'UTF8')) AS member_name, s.device_type, s.user_agent, s.login_dt, s.last_seen_dt, s.end_dt, s.end_reason, s.reg_ip, CASE WHEN THEN 'Y' ELSE 'N' END AS active_yn FROM login_session s LEFT JOIN member m ON m.member_id = s.member_id
ORDER BY s.login_session_id DESC LIMIT #{pageSize} OFFSET #{offset}

