UPDATE login_session
SET end_dt = NOW(), end_reason = #{endReason}
WHERE member_id = #{memberId} AND end_dt IS NULL

UPDATE login_session
SET end_dt = NOW(), end_reason = #{endReason}
WHERE login_session_id = #{rowId}::integer AND end_dt IS NULL
